    private val itemsById: Map<String, StickerItem> by lazy {
        PACKS.flatMap { it.items }.associateBy { it.id }
    }

    private val packsById: Map<String, StickerPack> by lazy {
        PACKS.associateBy { it.packId }
    }

    fun findById(id: String): StickerItem? = itemsById[id]

    fun findPack(packId: String): StickerPack? = packsById[packId]

    fun totalStickerCount(): Int = itemsById.size

    fun localizedTitle(item: StickerItem, locale: String?): String {
        if (!AppUiStrings.isArabic(locale)) return item.title
        val pack = findPack(item.packId)
        val arabicKeywords = item.keywords.filter { kw ->
            kw.any { ch -> ch in '\u0600'..'\u06FF' }
        }
        val specificAr = arabicKeywords.firstOrNull { it.isNotBlank() }
        return specificAr ?: pack?.titleAr ?: item.title
    }

    fun search(query: String, allowedPackIds: Set<String>? = null): List<StickerItem> {
        val q = query.trim().lowercase(Locale.ROOT)
        val pool = if (allowedPackIds == null) PACKS else PACKS.filter { it.packId in allowedPackIds }
        if (q.isEmpty()) return pool.flatMap { it.items }
        return pool.flatMap { pack ->
            val packMatches = pack.titleEn.lowercase(Locale.ROOT).contains(q) ||
                pack.titleAr.lowercase(Locale.ROOT).contains(q)
            pack.items.filter { item ->
                packMatches ||
                    item.title.lowercase(Locale.ROOT).contains(q) ||
                    item.keywords.any { it.lowercase(Locale.ROOT).contains(q) }
            }
        }
    }
}
